// Helper: bytes from hex (returns Uint8Array; '' -> empty buffer).
const _h2b = (h) => {
    if (!h) return new Uint8Array(0);
    const out = new Uint8Array(h.length >>> 1);
    for (let i = 0; i < out.length; i++) out[i] = parseInt(h.substr(i * 2, 2), 16);
    return out;
};
const _b2h = (b) => Array.from(b, (v) => v.toString(16).padStart(2, '0')).join('');

describe('ctrDRBG-1.0 (NIST CAVP CTR_DRBG-AES-256 no-df, ACVP-driven)', () => {
    test.each(_DRBG_AFT)('tgId=$tg tcId=$tc (predResistance=$pr, returnedBitsLen=$L)', (v) => {
        const d = _rng._internal.makeDrbg();
        // §10.2.1.3.1 instantiate (no df): seed_material = entropy XOR perso
        // (nonce empty for no-df because the entropy already carries 384 bits).
        expect(d.instantiate(_h2b(v.ent), v.pers ? _h2b(v.pers) : null)).toBe(true);

        const nBytes = v.L >>> 3;
        let lastOut = null;
        for (const oi of v.oi) {
            const ai  = oi.ai  ? _h2b(oi.ai)  : null;
            const ent = oi.ent ? _h2b(oi.ent) : null;
            if (oi.use === 'reSeed') {
                expect(d.reseed(ent, ai)).toBe(true);
            } else {
                // 'generate'
                if (v.pr) {
                    // §10.2.1.5.1 with prediction_resistance_request=true:
                    //   reseed first using supplied entropy + additionalInput,
                    //   then generate with empty additional_input.
                    expect(d.reseed(ent, ai)).toBe(true);
                    lastOut = d.generate(nBytes, null);
                } else {
                    lastOut = d.generate(nBytes, ai);
                }
                expect(lastOut).not.toBe(false);
            }
        }
        expect(lastOut).not.toBeNull();
        expect(_b2h(lastOut)).toBe(v.ret.toLowerCase());
    });
});

// ── Iteration H4 - CTR_DRBG-AES-{128,192,256} × {no-df, with-df} ────────────
//
// The `_makeDrbg` module accepts `{ aesKeyBits: 128|192|256, df: true|false }`
// (cf. random.js iteration H4). These tests execute ACVP NIST
// CAVP `ctrDRBG-1.0` predResistance=false vectors on the 6 combinations (3
// keyBits × 2 df modes), with sub-sample [first/mid/last] per group to
// keep CI cost minimal. Under `CRYPTO_FULL=1`, all 15
// tcId/group entries are executed.
const { readFileSync: _readFileSyncH4 } = await import('node:fs');
const _ACVP_CTRDRBG = JSON.parse(_readFileSyncH4(
    new URL('../../../tests/_vectors/ctrDRBG-1.0/internalProjection.json', import.meta.url),
    'utf8',
));
const _RUN_FULL_H4 = process.env.CRYPTO_FULL === '1';
function _h4Subsample(tests) {
    if (_RUN_FULL_H4 || tests.length <= 3) return tests;
    return [tests[0], tests[Math.floor(tests.length / 2)], tests[tests.length - 1]];
}
function _h4LoadCases({ mode, df }) {
    const out = [];
    for (const g of _ACVP_CTRDRBG.testGroups) {
        if (g.mode !== mode || g.derFunc !== df || g.predResistance) continue;
        for (const t of _h4Subsample(g.tests)) {
            out.push({
                tg: g.tgId, tc: t.tcId, mode, df, L: g.returnedBitsLen,
                ent: t.entropyInput, nonce: t.nonce || '',
                pers: t.persoString || '',
                oi: (t.otherInput || []).map(o => ({
                    use: o.intendedUse, ai: o.additionalInput || '', ent: o.entropyInput || '',
                })),
                ret: t.returnedBits,
            });
        }
    }
    return out;
}

const _MODES_H4 = [
    { mode: 'AES-128', kb: 128, df: false },
    { mode: 'AES-192', kb: 192, df: false },
    { mode: 'AES-128', kb: 128, df: true  },
    { mode: 'AES-192', kb: 192, df: true  },
    { mode: 'AES-256', kb: 256, df: true  },
];
for (const cfg of _MODES_H4) {
    const cases = _h4LoadCases({ mode: cfg.mode, df: cfg.df });
    if (cases.length === 0) continue;
    describe(`ctrDRBG-1.0 (NIST CAVP CTR_DRBG-${cfg.mode} ${cfg.df ? 'with-df' : 'no-df'}, iteration H4)`, () => {
        test.each(cases)('tgId=$tg tcId=$tc (returnedBitsLen=$L)', (v) => {
            const d = _rng._internal.makeDrbg({ aesKeyBits: cfg.kb, df: cfg.df });
            expect(d).not.toBe(false);
            // df-mode: instantiate(entropy, perso, nonce) ; no-df: instantiate(entropy, perso).
            const ok = cfg.df
                ? d.instantiate(_h2b(v.ent), v.pers ? _h2b(v.pers) : null, v.nonce ? _h2b(v.nonce) : null)
                : d.instantiate(_h2b(v.ent), v.pers ? _h2b(v.pers) : null);
            expect(ok).toBe(true);
            const nBytes = v.L >>> 3;
            let lastOut = null;
            for (const oi of v.oi) {
                const ai  = oi.ai  ? _h2b(oi.ai)  : null;
                const ent = oi.ent ? _h2b(oi.ent) : null;
                if (oi.use === 'reSeed') {
                    expect(d.reseed(ent, ai)).toBe(true);
                } else {
                    lastOut = d.generate(nBytes, ai);
                    expect(lastOut).not.toBe(false);
                }
            }
            expect(lastOut).not.toBeNull();
            expect(_b2h(lastOut)).toBe(v.ret.toLowerCase());
        });
    });
}
